import { ProductRepository } from '../../domain/product/ProductRepository';

/**
 * Stores snapshots rather than live entities, so changes only become
 * visible once a use case explicitly saves them.
 */
export class InMemoryProductRepository implements ProductRepository {
  private readonly records = new Map<string, ProductSnapshot>();

  findById(id: string): Product | undefined {
    const record = this.records.get(id);
    return record ? Product.restore(record) : undefined;
  }

  findAll(): Product[] {
    return [...this.records.values()].map((record) => Product.restore(record));
  }

  save(product: Product): void {
    this.records.set(product.id, product.toSnapshot());
  }
}

